import{_ as a,c as i,o as s,a3 as o}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"macOS 權限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/permissions.md","filePath":"zh-TW/guide/permissions.md","lastUpdated":1787284674000}'),e={name:"zh-TW/guide/permissions.md"};function n(r,t,l,c,p,h){return s(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="macos-權限" tabindex="-1">macOS 權限 <a class="header-anchor" href="#macos-權限" aria-label="Permalink to &quot;macOS 權限&quot;">​</a></h1><p>ClipboxAI 可能會請求幾項 macOS 權限，以提供最佳的體驗。本頁說明各項權限的用途以及如何管理它們。</p><h2 id="剪貼簿-自動化-clipboard-automation" tabindex="-1">剪貼簿／自動化（Clipboard / Automation） <a class="header-anchor" href="#剪貼簿-自動化-clipboard-automation" aria-label="Permalink to &quot;剪貼簿／自動化（Clipboard / Automation）&quot;">​</a></h2><p>為了在背景擷取你的剪貼簿並將結果貼回，ClipboxAI 使用了 macOS 的自動化（Automation）存取權限。</p><p><strong>用途</strong>：在你複製時讀取目前的剪貼板，並在你執行動作時將結果寫回。</p><p><strong>管理</strong>：<strong>System Settings → Privacy &amp; Security → Automation（系統設定 → 隱私權與安全性 → 自動化）</strong> → 啟用 <strong>ClipboxAI</strong>。</p><p>在首次啟動出現提示時授予存取權。你可以隨時管理或撤銷它。</p><h2 id="輔助使用-accessibility-選用" tabindex="-1">輔助使用（Accessibility）（選用） <a class="header-anchor" href="#輔助使用-accessibility-選用" aria-label="Permalink to &quot;輔助使用（Accessibility）（選用）&quot;">​</a></h2><p>某些建置版本會使用輔助使用權限，以提供全域鍵盤快捷鍵，並能從任何地方啟動歷史面板。</p><p><strong>用途</strong>：開啟歷史面板並透過熱鍵執行動作，即使應用程式不在焦點時也能運作。</p><p><strong>管理</strong>：<strong>System Settings → Privacy &amp; Security → Accessibility（系統設定 → 隱私權與安全性 → 輔助使用）</strong> → 啟用 <strong>ClipboxAI</strong>。</p><h2 id="通知-notifications-選用" tabindex="-1">通知（Notifications）（選用） <a class="header-anchor" href="#通知-notifications-選用" aria-label="Permalink to &quot;通知（Notifications）（選用）&quot;">​</a></h2><p>當長時間執行的動作完成或需要留意時，ClipboxAI 可能會顯示通知。</p><p><strong>用途</strong>：在動作完成或需要進行設定時提醒你。</p><p><strong>管理</strong>：<strong>System Settings → Notifications（系統設定 → 通知）</strong> → <strong>ClipboxAI</strong>。</p><h2 id="完全磁碟存取-full-disk-access-選用" tabindex="-1">完全磁碟存取（Full Disk Access）（選用） <a class="header-anchor" href="#完全磁碟存取-full-disk-access-選用" aria-label="Permalink to &quot;完全磁碟存取（Full Disk Access）（選用）&quot;">​</a></h2><p>一般使用不需要此權限。只有當你希望應用程式讀取位於系統保護位置中的剪貼內容時才需要。</p><p><strong>管理</strong>：<strong>System Settings → Privacy &amp; Security → Full Disk Access（系統設定 → 隱私權與安全性 → 完全磁碟存取）</strong>。</p><p>此權限為選用，僅在進階情境下才需要。</p><h2 id="使用終端機重設權限" tabindex="-1">使用終端機重設權限 <a class="header-anchor" href="#使用終端機重設權限" aria-label="Permalink to &quot;使用終端機重設權限&quot;">​</a></h2><p>如果權限對話框被關閉或狀態不一致，你可以使用 <code>tccutil</code> 重設 macOS 的權限提示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset automation/accessibility prompts for ClipboxAI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>執行 <code>tccutil</code> 後，請重新啟動應用程式並再次觸發該功能，以重新出現提示。</p><h2 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h2><ul><li>若剪貼簿歷史沒有捕捉到複製內容，請檢查是否已授予 <strong>Automation（自動化）</strong> 權限。</li><li>若全域快捷鍵無法運作，請檢查 <strong>Accessibility（輔助使用）</strong> 權限。</li><li>變更權限後，請務必退出並重新開啟 ClipboxAI，讓變更生效。</li></ul><p>如需更多協助，請參閱<a href="/zh-TW/guide/troubleshooting.html">疑難排解指南</a>。</p>`,26)])])}const u=a(e,[["render",n]]);export{g as __pageData,u as default};
